        if target.startswith('ansible_collections.') or target.startswith('ansible.module_utils.'):
            return tuple(target.split('.'))
        ref = AnsibleCollectionRef.from_fqcr(target, 'module_utils')
        return tuple((ref.n_python_package_name + '.' + ref.resource).split('.'))

