    def _routing_collection_name(self, candidate):
        return 'ansible.builtin'

    def _find_local(self, candidate):
        relative = candidate[self.root_length:]
        if not relative:
            return None
        paths = [os.path.join(path, *relative[:-1]) for path in self.mu_paths]
        try:
            info = ModuleInfo(relative[-1], paths)
            return info.get_source(), info.path, bool(info.pkg_dir), bool(info.py_src or info.pkg_dir)
        except (ImportError, AttributeError, TypeError):
            pass
        # Namespace-like directories also need an initializer in a zip payload.
        for path in paths:
            directory = os.path.join(path, relative[-1])
            if os.path.isdir(directory):
                return b'', os.path.join(directory, '__init__.py'), True, True
        return None


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    root_length = 5
    redirect_first = True

    def _routing_collection_name(self, candidate):
        return '.'.join(candidate[1:3])

    def _find_local(self, candidate):
        collection_name = self._routing_collection_name(candidate)
        if len(candidate) < 3:
            return b'', '/'.join(candidate) + '/__init__.py', True, True
        try:
            _get_collection_metadata(collection_name)
        except ValueError as exc:
            raise AnsibleError(to_native(exc))

        # The collection root, plugins, and module_utils packages are synthetic
        # in module payloads.  Their loader-side initializers are not plugin code.
        if len(candidate) <= self.root_length:
            return b'', '/'.join(candidate) + '/__init__.py', True, True

        collection_package = 'ansible_collections.' + collection_name
        collection = sys.modules.get(collection_package) or import_module(collection_package)
        if not getattr(collection, '__path__', None):
            return None
        relative = candidate[3:]
        root = collection.__path__[0]
        candidate_path = os.path.join(root, *relative)
        initializer = os.path.join(candidate_path, '__init__.py')
        if os.path.isdir(candidate_path):
            return (_slurp(initializer) if os.path.isfile(initializer) else b'',
                    initializer, True, True)
        module_path = candidate_path + '.py'
        if os.path.isfile(module_path):
            return _slurp(module_path), module_path, False, True
        return None


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    """Add all transitive module_utils dependencies to a module payload."""
    module_utils_paths = _module_utils_paths()
    written_paths = set(zf.namelist())
    pending = deque([('scan', name, module_fqn, data, False)])

    def include(parts, source, source_path, is_package=False):
        normalized = parts + (('__init__',) if is_package else ())
        output_path = '/'.join(normalized) + '.py'
        if normalized in py_module_names and output_path in written_paths:
            return
        if output_path not in written_paths:
            zf.writestr(output_path, source)
            written_paths.add(output_path)
        py_module_names.add(normalized)
        py_module_cache[normalized] = (source, source_path)
        pending.append(('scan', normalized[-1], '.'.join(parts), source, is_package))
        display.vvvvv('Using module_utils file %s' % to_text(source_path, errors='surrogate_or_strict'))

    # The wrapper imports basic and both base packages even for modules whose
    # own source has no module_utils imports.
    base_packages = (
        (('ansible',), b'from pkgutil import extend_path\n__path__=extend_path(__path__,__name__)\n'
         b'__version__="' + to_bytes(__version__) + b'"\n__author__="' + to_bytes(__author__) + b'"\n'),
        (('ansible', 'module_utils'), b'from pkgutil import extend_path\n__path__=extend_path(__path__,__name__)\n'),
    )
    for parts, default_source in base_packages:
        normalized = parts + ('__init__',)
        source, source_path = py_module_cache.get(normalized, (default_source, '/'.join(normalized) + '.py'))
        output_path = '/'.join(normalized) + '.py'
        if output_path not in written_paths:
            zf.writestr(output_path, source)
            written_paths.add(output_path)
        py_module_names.add(normalized)

    pending.append(('resolve', ('ansible', 'module_utils', 'basic'), False))

    while pending:
        work = pending.popleft()
        if work[0] == 'scan':
            _, source_name, source_fqn, source, is_package = work
            try:
                tree = compile(source, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
            except (SyntaxError, IndentationError) as exc:
                raise AnsibleError('Unable to import %s due to %s' % (source_name, exc.msg))
            finder = ModuleDepFinder(source_fqn, is_package=is_package)
            finder.visit(tree)
            for dependency in sorted(finder.submodules):
                if dependency[:3] == ('ansible', 'module_utils', 'six'):
                    # six installs virtual submodules into sys.modules itself.
                    dependency = dependency[:3]
                if dependency[:2] == ('ansible', 'module_utils') or (
                        dependency[:1] == ('ansible_collections',) and
                        dependency[3:5] == ('plugins', 'module_utils')):
                    pending.append(('resolve', dependency, dependency in finder.ambiguous_submodules))
            source_parts = tuple(source_fqn.split('.'))
            py_module_cache.pop(source_parts, None)
            if is_package:
                py_module_cache.pop(source_parts + ('__init__',), None)
            continue

        _, dependency, is_ambiguous = work
        if dependency[:3] == ('ansible', 'module_utils', 'six'):
            dependency = dependency[:3]
            is_ambiguous = False
        if dependency[:2] == ('ansible', 'module_utils'):
            locator = LegacyModuleUtilLocator(dependency, is_ambiguous, module_utils_paths)
        elif dependency[:1] == ('ansible_collections',) and dependency[3:5] == ('plugins', 'module_utils'):
            locator = CollectionModuleUtilLocator(dependency, is_ambiguous)
        else:
            continue

        if not locator.found or not locator.py_src:
            raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                               (module_fqn, locator.candidate_names_joined()))

        resolved = locator.normalized_name_parts[:-1] if locator.is_package else locator.normalized_name_parts
        # Include each parent initializer before the child.  A missing parent
        # is a synthetic package, including inside nested collection paths.
        for index in range(1, len(resolved)):
            parent = resolved[:index]
            parent_name = parent + ('__init__',)
            if parent_name in py_module_names and '/'.join(parent_name) + '.py' in written_paths:
                continue
            if parent[:2] == ('ansible', 'module_utils') and len(parent) > 2:
                parent_locator = LegacyModuleUtilLocator(parent, False, module_utils_paths,
                                                         child_is_redirected=locator.is_redirected)
            elif parent[:1] == ('ansible_collections',) and parent[3:5] == ('plugins', 'module_utils') and len(parent) > 5:
                parent_locator = CollectionModuleUtilLocator(parent, False, child_is_redirected=locator.is_redirected)
            else:
                parent_locator = None
            if parent_locator and parent_locator.found and parent_locator.is_package:
                include(parent, parent_locator.source_code, parent_locator.path, True)
            elif parent_name not in py_module_names:
                include(parent, b'', '<synthetic package>', True)

        include(resolved, locator.source_code, locator.path, locator.is_package)


def _is_binary(b_module_data):
    textchars = bytearray(set([7, 8, 9, 10, 12, 13, 27]) | set(range(0x20, 0x100)) - set([0x7f]))
    start = b_module_data[:1024]
    return bool(start.translate(None, textchars))


def _get_ansible_module_fqn(module_path):
    """
    Get the fully qualified name for an ansible module based on its pathname

    remote_module_fqn is the fully qualified name.  Like ansible.modules.system.ping
    Or ansible_collections.Namespace.Collection_name.plugins.modules.ping
    .. warning:: This function is for ansible modules only.  It won't work for other things
        (non-module plugins, etc)
    """
    remote_module_fqn = None

    # Is this a core module?
    match = CORE_LIBRARY_PATH_RE.search(module_path)
    if not match:
        # Is this a module in a collection?
        match = COLLECTION_PATH_RE.search(module_path)

    # We can tell the FQN for core modules and collection modules
    if match:
        path = match.group('path')
        if '.' in path:
            # FQNs must be valid as python identifiers.  This sanity check has failed.
            # we could check other things as well
            raise ValueError('Module name (or path) was not a valid python identifier')

        remote_module_fqn = '.'.join(path.split('/'))
    else:
        # Currently we do not handle modules in roles so we can end up here for that reason
        raise ValueError("Unable to determine module's fully qualified name")

    return remote_module_fqn


def _add_module_to_zip(zf, remote_module_fqn, b_module_data):
    """Add a module from ansible or from an ansible collection into the module zip"""
    module_path_parts = remote_module_fqn.split('.')

    # Write the module
    module_path = '/'.join(module_path_parts) + '.py'
    zf.writestr(module_path, b_module_data)

    # Write the __init__.py's necessary to get there
    if module_path_parts[0] == 'ansible':
        # The ansible namespace is setup as part of the module_utils setup...
        start = 2
        existing_paths = frozenset()
    else:
        # ... but ansible_collections and other toplevels are not
        start = 1
        existing_paths = frozenset(zf.namelist())

    for idx in range(start, len(module_path_parts)):
        package_path = '/'.join(module_path_parts[:idx]) + '/__init__.py'
        # If a collections module uses module_utils from a collection then most packages will have already been added by recursive_finder.
        if package_path in existing_paths:
            continue
        # Note: We don't want to include more than one ansible module in a payload at this time
        # so no need to fill the __init__.py with namespace code
        zf.writestr(package_path, b'')

